# Generated by the local console for one installation. No credentials included.
$ErrorActionPreference = 'Stop'
$CaptureRoot = __SILENCER_DATA_ROOT__
$CaptureStateRoot = __SILENCER_CAPTURE_ROOT__
$CapturePlatform = __SILENCER_PLATFORM__
$CaptureVerifier = __SILENCER_VERIFIER__
$CaptureManaged = '__SILENCER_MANAGED__' -eq 'true'
$CaptureKeepCA = '__SILENCER_KEEP_CA__' -eq 'true'
$CaptureCASha256 = __SILENCER_CA_SHA256__
if ($args.Count -or $CapturePlatform -ne 'windows' -or $env:OS -ne 'Windows_NT') { throw 'Run this script without arguments on its original Windows computer.' }
$CaptureWork = Join-Path ([IO.Path]::GetTempPath()) ('silencer-uninstall-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $CaptureWork | Out-Null
$CaptureServiceState = 'pending'
$CaptureCertificateState = 'pending'
$CaptureResult = 1
$CaptureReason = 'Verification pending / 尚未完成检查'
function Check-CaptureCurrentCA {
    $CurrentCA = Join-Path $CaptureStateRoot 'mitmproxy-ca-cert.pem'
    if (Test-Path $CurrentCA) {
        if (-not $CaptureCASha256) { throw 'CA changed after download; download a fresh script.' }
        $Identity = & $CaptureVerifier capture-check-ca $CurrentCA $CaptureCASha256 identity
        if ($LASTEXITCODE -ne 0 -or $Identity -ne 'matched') { throw 'CA identity changed; download a fresh script.' }
    }
}
[IO.Directory]::CreateDirectory($CaptureStateRoot) | Out-Null
$Report = Join-Path $CaptureStateRoot 'uninstall-report.html'
function Capture-StateLabel([string]$Value) {
    switch ($Value) {
        'removed' { '已移除并检查 / Removed and verified' }
        'retained' { '按选择保留 / Retained by choice' }
        'not-present' { '未生成证书 / No CA generated' }
        'unmanaged' { '未登记安装，未操作服务 / Unmanaged; service untouched' }
        'failed' { '需要处理 / Action required' }
        default { '尚未完成检查 / Not verified' }
    }
}
function Write-CaptureReport {
    $ServiceLabel = Capture-StateLabel $CaptureServiceState
    $CertificateLabel = Capture-StateLabel $CaptureCertificateState
    $Title = if ($CaptureResult -eq 0) { '卸载完成 / Uninstall complete' } elseif ($CaptureServiceState -eq 'pending') { '正在检查 / Verification pending' } else { '仍有步骤需要处理 / Action required' }

    $SafeReason = [System.Net.WebUtility]::HtmlEncode($CaptureReason)
    $Contents = @"
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Silencer 卸载报告 / Uninstall report</title>
<style>body{font:16px/1.8 system-ui;max-width:760px;margin:48px auto;padding:0 24px;color:#172033;background:#f8fafc}main{background:white;border:1px solid #dbe1ea;border-radius:16px;padding:28px}code{background:#edf2f7;padding:3px 6px}li{margin:12px 0}li[data-service],li[data-certificate]{list-style:none;border:1px solid #dbe1ea;border-radius:10px;padding:12px}li[data-service="removed"],li[data-certificate="removed"],li[data-certificate="not-present"]{border-color:#86d5b0;background:#effbf4}li[data-service="failed"],li[data-service="unmanaged"],li[data-certificate="failed"]{border-color:#f3c47b;background:#fff9ed}</style><main>
<h1>Silencer 卸载报告</h1><h2>$Title</h2><p>此报告来自脚本的实际检查。网页断开连接本身不代表卸载成功。</p>
<ul><li data-service="$CaptureServiceState">后台服务 / Service: <strong>$ServiceLabel</strong></li><li data-certificate="$CaptureCertificateState">证书信任 / CA trust: <strong>$CertificateLabel</strong></li><li>配置、证书文件、日志、映射及安装缓存已保留；远程处理端数据不受影响。</li></ul>

<p>检查说明 / Details: <strong>$SafeReason</strong></p><h2>仍需处理时</h2><p>查看终端错误，处理后可重复执行同一脚本。服务没有成功停止时，脚本不会继续清理证书。</p><p>按 Win+R 打开 certmgr.msc，在“受信任的根证书颁发机构 → 证书”按指纹核对本次 CA。手动导入到“本地计算机”的副本，需要以管理员身份打开 certlm.msc 清理；应用独立证书库也需单独移除副本。</p><p>本次 CA SHA-256：<code>$CaptureCASha256</code></p><p>系统代理、VPN、路由和 DNS 不作修改。</p></main></html>
"@
    [IO.File]::WriteAllText($Report, $Contents, [Text.UTF8Encoding]::new($true))

}
Write-CaptureReport
$CaptureServiceState = 'failed'
try {
    Check-CaptureCurrentCA
    if (-not $CaptureManaged) { $CaptureServiceState = 'unmanaged'; throw 'This instance is not a managed installation. No service was removed.' }
    if (Test-Path (Join-Path $CaptureRoot '.silencer-local-install')) {
        if ((Get-Content (Join-Path $CaptureRoot '.silencer-local-install') -Raw).Trim() -ne 'windows') { throw 'Installation identity changed' }
        $ExistingTasks = @(Get-ScheduledTask -ErrorAction Stop | Where-Object { $_.TaskName -eq 'Silencer Local' -and $_.TaskPath -eq '\' })
        foreach ($ExistingTask in $ExistingTasks) {
            $ExpectedArguments = '-NoProfile -WindowStyle Hidden -ExecutionPolicy RemoteSigned -File "' + (Join-Path $CaptureRoot 'launch.ps1') + '"'
            if ($ExistingTask.Actions.Count -ne 1 -or $ExistingTask.Actions[0].Arguments -ne $ExpectedArguments -or [IO.Path]::GetFileName($ExistingTask.Actions[0].Execute) -ne 'powershell.exe') { throw 'Service belongs to another installation; no service was removed.' }
        }
        $Installer = Join-Path $CaptureWork 'install.ps1'
        [IO.File]::WriteAllBytes($Installer, [Convert]::FromBase64String('__SILENCER_INSTALLER_BASE64__'))
        $PreviousDataDir = $env:SILENCER_DATA_DIR
        try {
            $env:SILENCER_DATA_DIR = $CaptureRoot
            & powershell.exe -NoProfile -ExecutionPolicy RemoteSigned -File $Installer -Uninstall
            if ($LASTEXITCODE -ne 0) { throw 'Service uninstall failed' }
        } finally { $env:SILENCER_DATA_DIR = $PreviousDataDir }
    }
    foreach ($Name in @('.silencer-local-install', 'current', 'launch.ps1')) {
        if (Test-Path (Join-Path $CaptureRoot $Name)) { throw 'Managed installation files remain' }
    }
    # Enumerate successfully before interpreting absence as completion.
    $Tasks = @(Get-ScheduledTask -ErrorAction Stop | Where-Object { $_.TaskName -eq 'Silencer Local' -and $_.TaskPath -eq '\' })
    if ($Tasks.Count) { throw 'Background task remains registered' }
    $Processes = @(Get-CimInstance Win32_Process -Filter "Name='silencer-gateway.exe' OR Name='mitmdump.exe'" | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith((Join-Path $CaptureRoot 'versions') + '\', [StringComparison]::OrdinalIgnoreCase) })
    if ($Processes.Count) { throw 'Background process is still running' }
    $CaptureServiceState = 'removed'
    $CaptureCertificateState = 'failed'
    Check-CaptureCurrentCA
    if ($CaptureKeepCA) { $CaptureCertificateState = 'retained' }
    elseif (-not $CaptureCASha256) { $CaptureCertificateState = 'not-present' }
    else {
        $CertificatePath = Join-Path $CaptureWork 'ca.crt'
        [IO.File]::WriteAllBytes($CertificatePath, [Convert]::FromBase64String('__SILENCER_CA_BASE64__'))
        $Certificate = [Security.Cryptography.X509Certificates.X509Certificate2]::new($CertificatePath)
        $Hasher = [Security.Cryptography.SHA256]::Create()
        try { $Fingerprint = [BitConverter]::ToString($Hasher.ComputeHash($Certificate.RawData)).Replace('-', '') } finally { $Hasher.Dispose() }
        if ($Fingerprint -ne $CaptureCASha256) { throw 'Public certificate identity mismatch' }
        $UserRoot = 'Cert:\CurrentUser\Root\' + $Certificate.Thumbprint
        if (Test-Path $UserRoot) { Remove-Item $UserRoot }
        if ((Test-Path $UserRoot) -or (Test-Path ('Cert:\LocalMachine\Root\' + $Certificate.Thumbprint))) { throw 'Certificate remains in a root store; use the system certificate manager' }
        $Trust = & $CaptureVerifier capture-check-ca $CertificatePath $CaptureCASha256 trust
        if ($LASTEXITCODE -ne 0 -or $Trust -ne 'untrusted') { throw 'CA trust is still present or could not be verified.' }
        $CaptureCertificateState = 'removed'
    }
    $CaptureResult = 0
    $CaptureReason = 'Selected cleanup completed and verified / 所选卸载操作已完成并检查'
} catch { $CaptureReason = $_.Exception.Message; Write-Warning $CaptureReason }
finally {
    # .NET file writing also runs during pipeline cancellation, leaving a fresh
    # pending/failed report instead of an old successful result.
    Write-CaptureReport
    Remove-Item -Recurse -Force $CaptureWork -ErrorAction SilentlyContinue
    try { Start-Process $Report } catch { }
}
Write-Output "Service: $CaptureServiceState`nCA trust: $CaptureCertificateState`nReport: $Report"
exit $CaptureResult
